<https://example.org/openevidence/questions/q_bipolar_disorder_efficacy> a holon:ClinicalQuestionHolon ;
    oe:questionText "How effective is lithium compared with other agents for Bipolar Disorder?"^^xsd:string ;
    oe:answerText "Bipolar disorder (BD), characterized by extreme mood shifts between mania and depression, can manifest in childhood, and pose treatment challenges. Treatment for full-criteria BD I or II in children has been partially described in the literature, but major uncertainties exist regarding non-classic presentations, which were originally designated as bipolar \"not otherwise specified\" (BP-NOS) in DSM-IV and in DSM-5 and ICD-11 as either other specified or unspecified BD (S-USBD)."^^xsd:string ;
    oe:belongsToSpecialty "Psychiatry" ;
    holon:hasInteriorGraph <https://example.org/openevidence/questions/q_bipolar_disorder_efficacy-int> ;
    holon:hasBoundaryGraph <https://example.org/openevidence/questions/q_bipolar_disorder_efficacy-bou> ;
    holon:hasProjectionGraph <https://example.org/openevidence/questions/q_bipolar_disorder_efficacy-pro> ;
    holon:hasContextGraph <https://example.org/openevidence/questions/q_bipolar_disorder_efficacy-con> ;
    holon:evidenceQualityThreshold "0.50"^^xsd:decimal .

<https://example.org/openevidence/drugs/lithium> oe:treats <https://example.org/openevidence/diseases/bipolar_disorder> .
